<?php
namespace App\Repository;
use App\Entity\HelloAssoPayment;use App\Entity\Participant;use App\Enum\HelloAssoPaymentMatchStatusEnum;use Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository;use Doctrine\ORM\QueryBuilder;use Doctrine\Persistence\ManagerRegistry;
/** @extends ServiceEntityRepository<HelloAssoPayment> */class HelloAssoPaymentRepository extends ServiceEntityRepository{public function __construct(ManagerRegistry $r){parent::__construct($r,HelloAssoPayment::class);}public function createAdminListQueryBuilder(?string $q,?string $state,?HelloAssoPaymentMatchStatusEnum $status,?string $association):QueryBuilder{$qb=$this->createQueryBuilder('h')->addSelect('p','s')->leftJoin('h.participant','p')->leftJoin('h.subscription','s')->orderBy('h.receivedAt','DESC');if($q){$qb->andWhere('LOWER(h.paymentId) LIKE :q OR LOWER(h.orderId) LIKE :q OR LOWER(h.payerEmail) LIKE :q OR LOWER(h.payerFirstname) LIKE :q OR LOWER(h.payerLastname) LIKE :q OR LOWER(p.internalReference) LIKE :q')->setParameter('q','%'.mb_strtolower(trim($q)).'%');}if($state){$qb->andWhere('h.paymentState = :state')->setParameter('state',$state);}if($status){$qb->andWhere('h.matchStatus = :status')->setParameter('status',$status);}if($association==='associated'){$qb->andWhere('h.participant IS NOT NULL');}elseif($association==='unassociated'){$qb->andWhere('h.participant IS NULL');}return $qb;}public function findUnresolved(?string $paymentId=null):array{$qb=$this->createQueryBuilder('h')->andWhere('h.matchStatus IN (:s)')->setParameter('s',HelloAssoPaymentMatchStatusEnum::unresolvedValues())->orderBy('h.receivedAt','ASC');if($paymentId){$qb->andWhere('h.paymentId = :pid')->setParameter('pid',$paymentId);}return $qb->getQuery()->getResult();}public function findByParticipant(Participant $p):array{return $this->findBy(['participant'=>$p],['receivedAt'=>'DESC']);}}
